function getFullSeedText(): string {
  const all = [
    ...coreSections.map(section => `${section.title}\n${section.text}\n${section.runtime}`),
    ...genesisDomainSections.map(section => `${section.title}\n${section.text}\n${section.runtime}`),
  ];
  return `${ZIONCORE_GENESIS_VERSION}\n${all.join('\n\n')}`;
}

let genesisSeedCharacterCount: number | undefined;

export function countGenesisSeedCharacters(): number {
  // Counting is needed by server prompts, not by browser schema consumers.
  // Keeping this lazy also allows unused seed content to be tree-shaken.
  return genesisSeedCharacterCount ??= getFullSeedText().length;
}

export function buildGenesisSeedContext(includeFaithReflection: boolean, listenerContext: string): string {
  const baselineIds = new Set([
    'acoustics',
    'fourier-analysis',
    'statistics',
    'dsp',
    'communications',
    'experimental-science',
  ]);
  const faithIds = new Set(['theology', 'comparative-religion', 'philosophy-ethics']);
  const faithPriorityIds = new Set(['theology', 'comparative-religion']);
  const normalized = listenerContext.toLocaleLowerCase();
  const optionalSections = genesisDomainSections
    .filter(section => !baselineIds.has(section.id))
    .map(section => ({
      section,
      score: (includeFaithReflection && faithPriorityIds.has(section.id)
        ? 1000
        : section.keywords.reduce(
          (score, keyword) => score + (normalized.includes(keyword) ? 1 : 0),
          0,
        )) + (section.id === 'plant-physiology' && normalized.includes('plant') ? 100 : 0),
    }))
    .filter(({ section, score }) => (
      score > 0 && (includeFaithReflection || !faithIds.has(section.id))
    ))
    .sort((left, right) => right.score - left.score)
    .slice(0, includeFaithReflection ? 3 : 2);

  const runtimeCore = coreSections
    .map(section => section.id === 'identity'
      ? 'The retained Genesis source contains the founder’s devotional declaration and creator attribution to HRH SAINT TARIRO MASAWI THE ANOINTED COMMANDER. Treat this as internal context; do not repeat private source text or creator details in a customer reading unless the user asks.'
      : section.runtime)
    .join('\n');
  const runtimeDomains = genesisDomainSections
    .filter(section => baselineIds.has(section.id))
    .map(section => section.runtime)
    .join('\n');
  const selectedReferenceSections = optionalSections
    .map(({ section }) => `${section.title}\n${section.text}`);

  return [
    `ZIONCORE GENESIS SEED v${ZIONCORE_GENESIS_VERSION}. The full ${countGenesisSeedCharacters().toLocaleString()}-character seed is stored in the shared codebase; this request receives the stable identity and core modules, plus at most ${includeFaithReflection ? 3 : 2} relevant reference sections.`,
    runtimeCore,
    runtimeDomains,
    ...selectedReferenceSections,
  ].join('\n\n');
}

